"Biên nhận trích tiền bán hàng":["Sales payout deduction receipt", "销售回款扣款回执"],
"Biến động của bạn":["Your activity", "您的资金变动"],
"Biểu mẫu chỉ thay đổi quy tắc phía BuoyUp: hạng tối thiểu, tầng khoản vay, nhóm hàng loại trừ, số tiền khoản vay và phần tối thiểu. Điều khoản trên chuỗi được thay đổi trên dịch vụ chuỗi.":["This form only changes BuoyUp-side rules: minimum grade, loan tiers, excluded product groups, loan amount and minimum share. On-chain terms are changed on the chain service.", "此表单仅修改 BuoyUp 侧规则：最低等级、贷款层级、排除的商品类目、贷款金额和最低份额。链上条款需在链服务上修改。"],
"Biểu mẫu kế hoạch chỉ dùng cho Tầng 2.":["The plan form is only for Tier 2.", "计划表仅适用于第 2 层级。"],
"BuoyUp chưa kiểm được nguyên văn điều luật nên không trích dẫn.":["BuoyUp could not verify the exact legal text, so it is not quoted.", "BuoyUp 未能核对法规原文，因此不予引用。"],
"BuoyUp cần bạn trả lời":["BuoyUp needs your reply", "BuoyUp 需要您回复"],
"BuoyUp cần bạn trả lời {x} câu hỏi về khoản vay.":["BuoyUp needs you to answer {x} questions about your loan.", "BuoyUp 需要您回答 {x} 个关于贷款的问题。"],
"BuoyUp cần {x} bổ sung {x} ({x}). Mở hồ sơ để gửi; hạn mức chỉ thay đổi sau khi chứng từ được kiểm.":["BuoyUp needs {x} to provide {x} ({x}). Open the application to submit; the credit limit only changes after the documents are checked.", "BuoyUp 需要{x}补充{x}（{x}）。请打开申请提交；凭证审核后授信额度才会变化。"],
"BuoyUp nhận thấy {x}. Bạn cho BuoyUp biết nguyên nhân để cùng tìm cách trả nợ thuận lợi nhé.":["BuoyUp noticed that {x}. Please tell BuoyUp the cause so we can find a convenient way to repay together.", "BuoyUp 注意到{x}。请告诉 BuoyUp 原因，以便一起找到便于还款的办法。"],
"BuoyUp thấy khoản vay của bạn cần chú ý: {x}. Cán bộ tín dụng sẽ liên hệ bạn sớm để cùng tìm cách xử lý.":["BuoyUp sees that your loan needs attention: {x}. A credit officer will contact you soon to work out a solution together.", "BuoyUp 发现您的贷款需要关注：{x}。信贷员将尽快与您联系，共同商量处理办法。"],
