"Bạn chưa có khoản vay nào.":["You don't have any loans yet.", "您还没有贷款。"],
"Bạn chưa gửi khiếu nại nào.":["You haven't filed any complaints.", "您尚未提交任何投诉。"],
"Bạn chọn số tiền và ngày trả trong hạn mức này; không cần duyệt lại. Kỳ hạn và hình thức trả do BuoyUp xác định.":["Choose the amount and repayment day within this credit limit; no re-approval needed. The term and repayment method are set by BuoyUp.", "您可在此授信额度内选择金额和还款日，无需重新审批。期限和还款方式由 BuoyUp 确定。"],
"Bạn cung cấp thông tin chính xác khi tạo tài khoản. Việc tạo tài khoản không phải là cam kết cấp tín dụng. Mọi đề xuất vốn cần được xác minh và xét duyệt theo hồ sơ.":["You provide accurate information when creating an account. Creating an account is not a commitment to extend credit. Every funding offer must be verified and reviewed based on the application.", "创建账户时，您应提供准确信息。创建账户并不代表承诺授信。所有资金方案均需根据申请材料进行核验和审批。"],
