"Bạn có thể ký":["You can sign now", "现在可以签署"],
"Bạn có thể nộp lại khi doanh thu tăng hoặc lịch sử tín dụng tốt hơn.":["You can reapply when revenue grows or your credit history improves.", "营收增长或信用记录改善后您可重新申请。"],
"Bạn có thể nộp lại khi hạng tín dụng cải thiện, hoặc liên hệ cán bộ tín dụng.":["You can reapply when your credit grade improves, or contact a credit officer.", "信用等级提升后您可重新申请，或联系信贷员。"],
"Bạn có thể quay lại bất cứ lúc nào.":["You can come back at any time.", "您可以随时回来继续。"],
"Bạn có thể đóng cửa sổ này; hồ sơ vẫn được lưu.":["You can close this window; your application stays saved.", "您可以关闭此窗口；申请会继续保存。"],
"Bạn có thể đóng và quay lại; hồ sơ vẫn được lưu.":["You can close and come back; your application stays saved.", "您可以关闭后再回来；申请会继续保存。"],
"Bạn cần cho phép BuoyUp dùng camera để xác thực khuôn mặt.":["You need to allow BuoyUp to use the camera for face verification.", "您需要允许 BuoyUp 使用摄像头进行人脸验证。"],
