"Bạn gửi hơi nhanh, đợi một phút rồi hỏi tiếp nhé.":["You're sending a bit fast; please wait a minute before asking again.", "您发送得有点快，请等一分钟再提问。"],
"Bạn gửi tin nhắn quá nhanh. Vui lòng thử lại sau một phút.":["You are sending messages too fast. Please try again in a minute.", "您发送消息过快。请一分钟后再试。"],
"Bạn không có quyền thực hiện thao tác này.":["You do not have permission to perform this action.", "您无权执行此操作。"],
"Bạn không có quyền với ngân hàng này.":["You do not have permission for this bank.", "您无权操作该银行。"],
"Bạn không có quyền xem hồ sơ này.":["You do not have permission to view this application.", "您无权查看此申请。"],
"Bạn không có quyền xem khoản vay này.":["You do not have permission to view this loan.", "您无权查看此贷款。"],
"Bạn kéo thanh trượt để chọn mức thấp hơn hạn mức đã duyệt, không cần duyệt lại. Lãi theo ngày, tổng phải trả và lịch trả do code tính lại theo số tiền bạn chọn.":["Drag the slider to choose an amount below the approved credit limit; no re-approval needed. Daily interest, total repayment and the schedule are recalculated by code for the amount you choose.", "拖动滑块即可选择低于已批授信额度的金额，无需重新审批。按日利息、总还款额和还款计划由系统按您选择的金额重新计算。"],
"Bạn luôn có thể yêu cầu gặp cán bộ trong quá trình tư vấn.":["You can always ask to speak with an officer during the advisory process.", "在咨询过程中，您随时可以要求与信贷员沟通。"],
