"Bạn đã thử đăng nhập nhiều lần. Vui lòng chờ một lúc rồi thử lại.":["You have tried to log in too many times. Please wait a moment and try again.", "登录尝试次数过多。请稍候再试。"],
"Bạn đã trả hết khoản vay. BuoyUp đã báo trung tâm thông tin tín dụng. Từ giờ bạn có thể đổi tài khoản nhận tiền hàng; khi cần vốn, bạn vay lại với hồ sơ cập nhật.":["You have fully repaid the loan. BuoyUp has reported it to the credit bureau. You can now change the payout receiving account; when you need capital, you can borrow again with an updated application.", "您已还清贷款。BuoyUp 已报送征信中心。现在您可以更换回款收款账户；需要资金时，可凭更新后的资料再次借款。"],
