"Bộ điều phối gửi hồ sơ cho các ngân hàng cùng lúc; mỗi ngân hàng tự tra cứu tín dụng và trả lời trong 30 giây. Hai đối tác đồng ý: 40/30/30; một đối tác: 30/70. Phần quyết định của ngân hàng được tính theo chính sách đã khai.":["The coordinator sends the application to all banks at once; each bank runs its own credit check and replies within 30 seconds. Two partners agree: 40/30/30; one partner: 30/70. The bank decision part is computed from the declared policy.", "协调器同时将申请发送给各银行；每家银行自行查询征信并在 30 秒内答复。两家合作方同意：40/30/30；一家合作方：30/70。银行决策部分根据已申报的政策计算。"],
