"Chụp hai mặt CCCD để BuoyUp đọc thông tin, rồi quét khuôn mặt để xác nhận đúng là bạn. Ảnh CCCD chỉ được đọc, không được lưu lại.":["Photograph both sides of your ID card so BuoyUp can read the details, then scan your face to confirm it is really you. ID card photos are only read, never stored.", "拍摄身份证正反两面，供 BuoyUp 读取信息，然后进行人脸扫描以确认是您本人。身份证照片仅用于读取，不会被保存。"],
