"Các ngân hàng chuyển vốn vào tài khoản trung gian tại WeBank, rồi giải ngân cho bạn.":["The banks transfer funds to an intermediary account at WeBank, which then disburses to you.", "各银行将资金转入 WeBank 的中间账户，再向您放款。"],
"Các ngân hàng có xem được dữ liệu của nhau?":["Can banks see each other's data?", "各银行能看到彼此的数据吗？"],
"Các ngân hàng cùng chấm điểm rủi ro mà dữ liệu gốc không rời ngân hàng. Chỉ thực hiện trong phạm vi bạn đã ủy quyền.":["Banks jointly score risk without raw data ever leaving each bank. Only performed within the scope you have consented to.", "各银行联合进行风险评分，原始数据不出行。仅在您授权的范围内进行。"],
"Các ngân hàng duyệt song song":["Banks review in parallel", "各银行并行审批"],
"Các ngân hàng đang duyệt":["Banks are reviewing", "银行审核中"],
"Các ngân hàng đối tác cùng cấp vốn theo tỷ lệ và chính sách riêng. Tiền đến người vay hoặc nhà cung cấp đã kiểm tra; tiền bán hàng về được phân bổ trả nợ theo tỷ lệ.":["Partner banks co-lend according to their own shares and policies. Funds go to the borrower or to a verified supplier; incoming sales proceeds are allocated to repayment by share.", "合作银行按各自比例和政策联合出资。资金发放给借款人或经核验的供应商；销售回款按比例分配用于还款。"],
"Các ngân hàng đối tác duyệt hạn mức {x} tệ, thấp hơn mức {x} tệ BuoyUp tính được.":["Partner banks approved a credit limit of {x} CNY, lower than the {x} CNY BuoyUp calculated.", "合作银行批准的授信额度为 {x} 元，低于 BuoyUp 计算的 {x} 元。"],
