"Còn {x} ngày đến kỳ {x} ({x}): khoảng {x}{x}. Số dư tài khoản kinh doanh {x}.":["{x} days until instalment {x} ({x}): about {x}{x}. Business account balance {x}.", "距第 {2} 期（{3}）还有 {1} 天：约 {4}{5}。经营账户余额 {6}。"],
"Còn {x} ngày đến kỳ {x} ({x}): phải trả {x} tệ{x}. Số dư {x} tệ; {x}, đến ngày trả dự kiến có khoảng {x} tệ, thiếu khoảng {x} tệ. Bạn có thể nộp thêm vào tài khoản WeBank":["{x} days until instalment {x} ({x}): {x} CNY due{x}. Balance {x} CNY; {x}, by the repayment day you should have about {x} CNY, short by about {x} CNY. You can top up the WeBank account", "距第 {2} 期（{3}）还有 {1} 天：应还 {4} 元{5}。余额 {6} 元；{7}，到还款日预计约有 {8} 元，缺口约 {9} 元。您可以向 WeBank 账户补充资金"],
"Có":["Yes", "是"],
"Có cờ cần cán bộ xem ở bước kiểm tra bất thường":["Anomaly check raised a flag for officer review", "异常检查环节有需信贷员复核的标记"],
"Có cờ đã giải thích nhưng chưa kiểm được, hoặc thiếu đối tác dữ liệu":["Flags explained but not verified, or a data partner is missing", "有已解释但未核实的标记，或缺少数据合作方"],
"Có hai cách trả, chọn một lần khi ký: (1) Trả góp cố định: gốc chia đều mỗi tháng, cộng lãi tính theo số ngày thực tế trên dư nợ còn lại; số tiền mỗi tháng giảm dần. (2) Trả theo doanh thu: mỗi tháng trả một tỷ lệ doanh thu về tài khoản kinh doanh WeBank":["There are two repayment methods, chosen once at signing: (1) Fixed instalments: principal split equally each month, plus interest on actual days on the remaining balance; the monthly amount decreases. (2) Revenue-based: each month you repay a share of the revenue flowing into the WeBank business account", "共有两种还款方式，签约时一次选定：(1) 固定分期：本金每月平均分摊，加上按实际天数对剩余本金计算的利息；每月金额递减。(2) 按营收还款：每月按进入 WeBank 经营账户营收的一定比例还款"],
"Có khoản nợ chưa được kê khai so với báo cáo tín dụng":["Has debts not declared compared with the credit report", "存在与征信报告相比未申报的债务"],
"Có khoản quá hạn":["Has an overdue loan", "存在逾期贷款"],
"Có liên kết với đối tượng đã bị ghi nhận rủi ro trước đây":["Linked to a party previously recorded as a risk", "与曾被记录为风险的对象存在关联"],
"Có nợ xấu đang hoạt động":["Active bad debt", "存在未结清不良贷款"],
"Có phần không giải mã được: bản mã đã bị sửa hoặc không khớp mã lệnh.":["Some parts could not be decrypted: the ciphertext was altered or does not match the order code.", "部分内容无法解密：密文已被篡改或与指令编号不匹配。"],
"Có thể thiếu tiền kỳ tới":["Possible shortfall next instalment", "下期可能资金不足"],
"Có thể đủ điều kiện từ {x}.":["You may be eligible from {x}.", "您可能自 {x} 起符合条件。"],
"Có tra cứu tín dụng mới ở nơi khác":["New credit inquiry elsewhere", "其他机构有新的征信查询"],
"Có {x} tệ chi chưa phân loại":["{x} CNY of spending not categorized", "有 {x} 元支出未分类"],
"Có đăng ký doanh nghiệp · cần bảo lãnh của người đại diện":["Registered company · requires a guarantee from the legal representative", "已办理企业登记 · 需法定代表人担保"],
"Có đăng ký hộ kinh doanh · vay tối đa 200.000 tệ":["Registered household business · borrow up to 200,000 CNY", "已办理个体工商户登记 · 最高可借 200,000 元"],
"Công cụ":["Tool", "工具"],
"Công khai":["Public", "公开"],
"Công khai: mã, thời điểm, số mảnh và kích thước; không công khai ngân hàng trong bản ghi mã hóa. Khóa đã lộ có thể đọc bản ghi cũ vĩnh viễn. Mỗi ngân hàng không tự kiểm được tổng tỷ lệ các phần.":["Public: ID, timestamp, number of shards and size; banks are not revealed in the encrypted record. A leaked key can read old records forever. No single bank can verify the total of all shares on its own.", "公开：编号、时间、分片数量和大小；加密记录中不公开银行信息。已泄露的密钥可永久读取旧记录。各银行无法自行核验各份额的比例总和。"],
"Công khai: mã, thời điểm, số mảnh và kích thước; không công khai ngân hàng trong bản ghi mã hóa. Khóa đã lộ có thể đọc bản ghi cũ vĩnh viễn. Mỗi ngân hàng không tự kiểm được tổng tỷ lệ các phần. Trong chế độ cục bộ, bốn nút chạy trên cùng một máy với một đơn vị vận hành, dùng ngân quỹ nội bộ và hàm băm sha3-256. Khóa chủ thực tế phải nằm trong HSM/KMS.":["Public: code, timestamp, number of shards and size; the banks in the encrypted record are not disclosed. A leaked key can read old records forever. No single bank can verify on its own the total of all shares. In local mode, the four nodes run on one machine under one operator, with an internal treasury and the sha3-256 hash. In production, the master key must reside in an HSM/KMS.", "公开内容：编号、时间、分片数量和大小；加密记录中的银行不公开。密钥一旦泄露，可永久读取旧记录。各银行无法自行核对各部分比例之和。在本地模式下，四个节点位于同一台机器、由同一运营方运行，使用内部资金库和 sha3-256 哈希。实际部署中主密钥必须存放在 HSM/KMS 中。"],
"Cùng cấp vốn.":["Funding together.", "共同出资，"],
"Cùng nâng bước.":["Rising together.", "共同成长。"],
"Cùng xem bạn có thể vay bao nhiêu.":["Let's see how much you can borrow.", "一起看看您能借多少。"],
