"Danh sách: WeBank (dẫn đầu, giữ 30–40%); China Merchants Bank; Industrial and Commercial Bank of China; Bank of China; China Construction Bank; Guangzhou Rural Commercial Bank (chỉ cho vay trong tỉnh Quảng Đông).":["List: WeBank (lead, holding 30–40%); China Merchants Bank; Industrial and Commercial Bank of China; Bank of China; China Construction Bank; Guangzhou Rural Commercial Bank (lends only within Guangdong Province).", "名单：WeBank（牵头，持有 30–40%）；China Merchants Bank（招商银行）；Industrial and Commercial Bank of China（中国工商银行）；Bank of China（中国银行）；China Construction Bank（中国建设银行）；Guangzhou Rural Commercial Bank（广州农村商业银行，仅在广东省内放款）。"],
