"Doanh nghiệp vay vốn lưu động có trần cao hơn, kèm bảo lãnh của người đại diện.":["Enterprises borrowing working capital have a higher cap, with a guarantee from the legal representative.", "企业流动资金贷款上限更高，需法定代表人提供担保。"],
