"Dán link cửa hàng do chính chị đăng ký.":["Paste the link of a store registered by you.", "请粘贴您本人注册的店铺链接。"],
"Dán link cửa hàng, xác minh danh tính và ủy quyền. Các AI agent phối hợp xuyên suốt hành trình; mọi con số đều do giải thuật tính, có đầu vào để đối chiếu.":["Paste your store link, verify your identity and grant consent. AI agents work together throughout the journey; every figure is calculated by algorithms, with inputs you can cross-check.", "粘贴店铺链接，完成身份验证并授权。多个 AI agent 全程协同；所有数字均由算法计算，输入数据可供核对。"],
"Dán link gian hàng của bạn":["Paste your store link", "粘贴您的店铺链接"],
"Dán link để BuoyUp đọc thông tin cửa hàng.":["Paste a link so BuoyUp can read your store information.", "粘贴链接，BuoyUp 将读取您的店铺信息。"],
"Dán ít nhất một link cửa hàng hoặc nhập số đăng ký.":["Paste at least one store link or enter a registration number.", "请至少粘贴一个店铺链接或输入登记号。"],
"Dán ít nhất một link gian hàng.":["Paste at least one store link.", "请至少粘贴一个店铺链接。"],
