"Dòng tiền thông suốt":["Smooth cash flow", "现金流畅通"],
"Dòng tiền thực về tài khoản không khớp với tiền nền tảng đã thanh toán":["Actual cash inflow to the account does not match platform payouts", "账户实际入账与平台已结算金额不符"],
"Dòng vốn đúng lúc.":["Capital at the right time.", "资金及时到位，"],
"Dùng cửa hàng của chủ thể đang hoạt động, hoặc khôi phục đăng ký rồi nộp lại.":["Use a store of an active entity, or restore the registration and reapply.", "请使用存续主体的店铺，或恢复登记后重新申请。"],
"Dùng gian hàng mẫu":["Use a sample store", "使用示例店铺"],
"Dùng trình giải mã và khóa của dịch vụ chuỗi. Xem cách chạy bằng --help.":["Use the chain service's decryptor and key. See --help for how to run it.", "使用链服务的解密工具和密钥。运行方法见 --help。"],
"Dùng vốn sai mục đích (chứng khoán / bất động sản)":["Misuse of loan funds (securities / real estate)", "贷款资金挪用（证券 / 房地产）"],
"Dùng vốn:":["Use of funds:", "资金用途："],
"Dùng ít nhất tám ký tự, có chữ và số.":["Use at least eight characters, with letters and numbers.", "至少八个字符，需包含字母和数字。"],
