"Dư nợ tầng 2 của cùng sự kiện, cộng hạn mức hồ sơ này, vượt giới hạn danh mục theo sự kiện hoặc theo ngành hàng":["Tier 2 exposure for the same event, plus this application's limit, exceeds the portfolio limit per event or per product category", "同一活动的第 2 层级未偿余额加上本申请额度，超出按活动或按商品类别设定的组合上限"],
