"Dẫn đầu":["Lead", "牵头行"],
"Dịp bán hàng":["Sales occasion", "销售节点"],
"BẢN CHỤP":["SNAPSHOT", "快照"],
"Dữ liệu":["Data", "数据"],
"Dữ liệu chi tiết":["Detailed data", "详细数据"],
"Dữ liệu cá nhân":["Personal data", "个人数据"],
"Dữ liệu các khối do lõi tính toán trả về.":["Block data returned by the calculation core.", "各模块数据由计算核心返回。"],
"Dữ liệu có căn cứ":["Evidence-based data", "有据可查的数据"],
"Dữ liệu của bạn.":["Your data.", "您的数据，"],
"Dữ liệu gốc được giữ tại từng ngân hàng. FATE phối hợp đánh giá rủi ro; mỗi ngân hàng chỉ giải mã được phần lệnh giải ngân dành cho mình.":["Raw data stays at each bank. FATE coordinates risk assessment; each bank can only decrypt the part of the disbursement order intended for it.", "原始数据保留在各银行。FATE 协同进行风险评估；每家银行只能解密发给自己的那部分放款指令。"],
"Dữ liệu gửi lên không hợp lệ.":["The submitted data is invalid.", "提交的数据无效。"],
"Dữ liệu khai báo không khớp nguồn đối chiếu bên ngoài":["Declared data does not match external reference sources", "申报数据与外部核对来源不符"],
"Dữ liệu khối":["Block data", "区块数据"],
"Dữ liệu liên ngân hàng còn ít":["Limited interbank data", "跨行数据较少"],
"Dữ liệu liên ngân hàng còn ít: hạn mức có trần thấp hơn cho đến khi có thêm lịch sử":["Limited interbank data: lower credit-limit cap until more history is available", "跨行数据较少：在积累更多记录前授信上限较低"],
"Dữ liệu mẫu":["Sample data", "样本数据"],
"Dữ liệu thật":["Live data", "真实数据"],
"Dữ liệu tài chính do API cung cấp. Mọi thao tác được ghi vào nhật ký.":["Financial data is provided by the API. Every action is written to the log.", "金融数据由 API 提供。所有操作都会记录到日志中。"],
"Chỉ chia sẻ dữ liệu tài chính sau khi bạn đã xem và đồng ý phạm vi ủy quyền của từng hồ sơ.":["Financial data is shared only after you have reviewed and agreed to the consent scope of each application.", "只有在您查看并同意每份申请的授权范围后，才会共享财务数据。"],
"Dự báo":["Forecast", "预测"],
"Dự báo thận trọng":["Conservative forecast", "审慎预测"],
"Dự kiến":["Scheduled", "计划金额"],
"Dự kiến có kết quả trước {x}.":["Result expected before {x}.", "预计在 {x} 前出结果。"],
"Dự án và hồ sơ":["Projects and applications", "项目与申请"],
"Em chưa trả lời chính xác được câu này. Bạn hỏi lại cụ thể hơn, hoặc bấm “Tôi muốn gặp cán bộ” nhé.":["I can't answer this question accurately yet. Please ask more specifically, or tap “I want to talk to an officer”.", "我暂时无法准确回答这个问题。请您问得更具体一些，或点击“我想联系信贷员”。"],
"Em chỉ chọn được một trong các phương án giải thuật đã tính: {x} tệ. Nếu bạn muốn xin mức khác, em có thể chuyển hồ sơ cho cán bộ.":["I can only choose one of the calculated options: {x} CNY. If you want a different amount, I can forward the application to an officer.", "我只能从已计算的方案中选择一个：{x} 元。如果您想申请其他金额，我可以将申请转交信贷员。"],
"Em chỉ trả lời được về hồ sơ và số liệu đã xác minh của bạn.":["I can only answer about your application and its verified figures.", "我只能回答与您的申请及已核验数据相关的问题。"],
"Em có thể giải thích từng yếu tố, thử phương án khi bạn đổi vốn hoặc số lượng nhập, hoặc chuyển bạn gặp cán bộ.":["I can explain each factor, test options when you change capital or purchase quantity, or connect you with an officer.", "我可以解释每个因素，在您调整资金或进货数量时试算方案，或为您转接信贷员。"],
"Em không có công cụ nào duyệt mức ngoài các phương án đã tính. Bạn có thể nộp kênh thủ công, hoặc bấm “Tôi muốn gặp cán bộ” để em chuyển yêu cầu ngay. Trong hạn mức đã duyệt, bạn tự chọn số tiền, kỳ hạn và cách trả mà không cần duyệt lại.":["I have no tool to approve amounts beyond the calculated options. You can apply via the manual channel, or tap “I want to talk to an officer” and I will forward your request right away. Within the approved credit limit, you choose the amount, term and repayment method yourself without re-approval.", "除已计算的方案外，我没有任何工具可以批准其他金额。您可以通过人工渠道申请，或点击“我想联系信贷员”，我会立即转交您的请求。在已批准的授信额度内，您可自行选择金额、期限和还款方式，无需重新审批。"],
"Em không đọc tài liệu gửi qua tin nhắn. Em đã ghi yêu cầu bổ sung {x} (mã {x}) để bước xác minh kiểm tra; dữ liệu mới chỉ ảnh hưởng tới số tiền sau khi được xác minh. Phương án hiện tại vẫn giữ nguyên.":["I don't read documents sent via chat. I have logged a request to provide {x} (code {x}) for verification; new data only affects the amount after it is verified. The current option stays unchanged.", "我不读取通过消息发送的文件。我已登记补充{x}的请求（编号 {x}）交由核验环节检查；新数据仅在核验后才会影响金额。当前方案保持不变。"],
"Em đã chuyển hồ sơ cho cán bộ tín dụng xem.":["I have forwarded the application to a credit officer for review.", "我已将申请转交信贷员审核。"],
"Em đã chuyển yêu cầu của bạn tới cán bộ tín dụng. Hồ sơ có yêu cầu người xem sẽ không duyệt tự động.":["I have forwarded your request to a credit officer. Applications with a human review request are not auto-approved.", "我已将您的请求转交信贷员。提出人工审核请求的申请不会自动审批。"],
"Em đã xem hồ sơ, dòng tiền và đề xuất của bạn. Cùng xem khoản vay hoặc lên kế hoạch cho mùa bán hàng nhé.":["I've reviewed your application, cash flow and offer. Let's look at your loan or plan for the sales season.", "我已查看了您的申请、现金流和方案。一起看看您的贷款，或为销售旺季做规划吧。"],
