"Không đồng ý với kết quả? Bạn có thể gửi khiếu nại ngay tại đây hoặc qua {x}.":["Disagree with the result? You can submit a complaint right here or via {x}.", "对结果有异议？您可以直接在此提交投诉，或通过 {x} 提交。"],
"Không đồng ý với một quyết định, khoản phí hay lần trích nợ? Gửi cho BuoyUp tại đây. Lý do đã ghi trong hồ sơ được đính kèm tự động; người xem xét là cán bộ khác người đã quyết định.":["Disagree with a decision, a fee or a deduction? Send it to BuoyUp here. The reasons recorded in your file are attached automatically; the reviewer is a different officer from the one who made the decision.", "对某项决定、费用或扣款有异议？请在此提交给 BuoyUp。档案中记录的理由将自动附上；复核人是与原决定人不同的信贷员。"],
