"Mỗi ngân hàng tham gia giữ ít nhất 30% khoản vay và ký hợp đồng riêng với tôi. Hai đối tác đồng ý: WeBank 40%, mỗi đối tác 30%. Một đối tác: WeBank 30%, đối tác 70%. Không ai đồng ý: hạn mức được thử lại ở mức thấp hơn, rồi từ chối.":["Each participating bank holds at least 30% of the loan and signs a separate contract with me. Two partners agree: WeBank 40%, each partner 30%. One partner: WeBank 30%, partner 70%. No one agrees: the limit is retried at a lower amount, then declined.", "每家参与银行至少持有贷款的 30%，并与本人单独签订合同。两家合作银行同意：WeBank 40%，每家合作银行各 30%。一家合作银行同意：WeBank 30%，该合作银行 70%。均不同意：以较低额度重新尝试，仍不成功则拒绝。"],
"Mỗi người vay chỉ có một khoản vay tại một thời điểm.":["Each borrower may have only one loan at a time.", "每位借款人同一时间只能有一笔贷款。"],
