"Trả lời có lý do trong 5 ngày làm việc.":["Reasoned reply within 5 business days.", "5 个工作日内附理由答复。"],
"Trả lời có lý do trong 5 ngày làm việc; người xem xét khác cán bộ đã quyết định; quá hạn tự chuyển trưởng nhóm.":["Reply with reasons within 5 working days; the reviewer must differ from the officer who decided; overdue cases escalate to the team lead automatically.", "须在 5 个工作日内附理由答复；复核人不得为原决策信贷员；逾期自动转交组长。"],
