"Trả tối thiểu":["Minimum paid", "已付最低还款"],
"Trả tối thiểu (chỉ hình thức trả góp, kỳ hạn từ {x} tháng): lãi kỳ + {x}% gốc của một kỳ; tối đa {x} kỳ liên tiếp.":["Minimum payment (fixed instalments only, term from {x} months): instalment interest + {x}% of one instalment's principal; up to {x} consecutive instalments.", "最低还款（仅限分期方式，期限 {x} 个月起）：当期利息 + 一期本金的 {x}%；最多连续 {x} 期。"],
"Trả tối thiểu chỉ áp dụng cho hình thức trả góp cố định.":["Minimum payment only applies to fixed instalments.", "最低还款仅适用于固定分期方式。"],
"Trả tối thiểu cần kỳ hạn từ {x} tháng.":["Minimum payment requires a term of at least {x} months.", "最低还款要求期限至少 {x} 个月。"],
"Trả tốt khoản vay qua BuoyUp giúp bạn lên nhóm có trần cao hơn ở lần vay sau.":["Repaying a BuoyUp loan well moves you to a group with a higher cap on your next loan.", "良好偿还 BuoyUp 贷款，下次借款时可升至上限更高的客群。"],
"Trả đúng hạn các khoản đang có và nộp lại sau.":["Repay your current loans on time and reapply later.", "请按时偿还现有贷款，稍后再申请。"],
"Trả đúng hạn và để tiền bán hàng về tài khoản kinh doanh WeBank đều đặn; từ khoản sau hạn mức được nâng dần tới mức đầy đủ.":["Repay on time and keep sales proceeds flowing into your WeBank business account regularly; from the next loan the credit limit rises gradually to the full amount.", "按时还款，并让销售回款稳定进入您的 WeBank 经营账户；从下一笔贷款起，授信额度会逐步提高到全额。"],
