"Trợ lý BuoyUp":["BuoyUp assistant", "BuoyUp 助手"],
"Trợ lý BuoyUp sẵn sàng khi hồ sơ của bạn đã được xác minh. Trợ lý trả lời về hạn mức, doanh thu, lịch trả và các ngân hàng cho vay.":["The BuoyUp assistant is available once your application is verified. It answers questions about your limit, revenue, repayment schedule and the lending banks.", "您的申请通过核验后即可使用 BuoyUp 助手。助手可解答关于额度、营业额、还款计划和放款银行的问题。"],
