"Tóm tắt":["Summary", "摘要"],
"Tóm tắt chính sách":["Policy summary", "政策摘要"],
"Tóm tắt được phép đọc":["Readable summary", "可查看摘要"],
"Tôi cam kết dùng vốn cho kinh doanh, không mua chứng khoán, bất động sản hay cho vay lại.":["I commit to using the funds for business, not to buy securities or real estate or to re-lend.", "本人承诺资金用于经营，不用于购买证券、房地产或转贷。"],
"Tôi cam đoan các thông tin trong kế hoạch vay, số liệu doanh thu và ảnh chụp tôi tải lên là đúng sự thật và do tôi tự kê khai. Tôi hiểu rằng kê khai gian dối để được cấp vốn có thể bị từ chối, thu hồi khoản vay trước hạn và chịu trách nhiệm theo pháp luật.":["I declare that the information in the loan plan, the revenue figures and the screenshots I uploaded are true and were declared by me. I understand that false declarations to obtain funding may lead to rejection, early recall of the loan and liability under the law.", "本人承诺，借款计划中的信息、营收数据及本人上传的截图均真实，且由本人自行申报。本人理解，为获得资金而虚假申报可能导致申请被拒、贷款被提前收回，并须依法承担责任。"],
"Tôi cam đoan số doanh thu và ảnh chụp tôi tải lên là của cửa hàng tôi, lấy từ trang quản lý cửa hàng và không bị chỉnh sửa.":["I declare that the revenue figures and screenshots I upload belong to my store, were taken from the store management page and have not been edited.", "本人承诺所上传的营业额数据和截图属于本人店铺，取自店铺管理后台，且未经修改。"],
"Tôi cam đoan toàn bộ thông tin trong kế hoạch vay là đúng sự thật và do tôi tự kê khai. Tôi hiểu rằng kê khai gian dối có thể bị từ chối, bị thu hồi khoản vay trước hạn và chịu trách nhiệm theo pháp luật.":["I declare that all information in the loan plan is true and was declared by me. I understand that false declarations may lead to rejection, early recall of the loan and legal liability.", "本人承诺贷款计划中的全部信息真实，且由本人自行申报。本人知悉虚假申报可能导致申请被拒、贷款被提前收回，并须承担法律责任。"],
"Tôi cần chuẩn bị gì để bắt đầu?":["What do I need to get started?", "开始前需要准备什么？"],
"Tôi hiểu kỳ {x} hệ thống trích {x} vào ngày {x}; phần gốc {x} chia cho các kỳ sau và lãi vẫn tính trên dư nợ gốc còn lại.":["I understand that for installment {x} the system will deduct {x} on {x}; the principal of {x} is spread over later installments and interest still accrues on the remaining outstanding principal.", "我了解第 {1} 期系统将于 {3} 扣款 {2}；本金 {4} 分摊至后续各期，利息仍按剩余本金计算。"],
"Tôi hiểu {x} sẽ được trích ngay từ tài khoản kinh doanh WeBank và không hoàn lại được.":["I understand that {x} will be deducted immediately from my WeBank business account and cannot be refunded.", "我了解 {x} 将立即从我的 WeBank 经营账户扣除，且无法退回。"],
"Tôi muốn bổ sung chứng từ cho hồ sơ.":["I want to add documents to the application.", "我想为申请补充材料。"],
"Tôi muốn bổ sung chứng từ: hóa đơn mua vào hoặc báo giá của xưởng cho lô hàng này.":["I want to add documents: purchase invoices or a factory quotation for this batch of goods.", "我想补充材料：本批货物的进货发票或工厂报价单。"],
"Tôi muốn bổ sung chứng từ: ảnh kho hoặc phiếu nhập cho số tồn kho.":["I want to add documents: warehouse photos or goods receipts for the inventory.", "我想补充材料：库存的仓库照片或入库单。"],
"Tôi muốn gặp cán bộ":["I'd like to talk to an officer", "我想联系信贷员"],
"Tôi muốn xét lại mức đầy đủ cho hồ sơ này.":["I want a full reassessment of this application.", "我想对此申请进行全面重新评估。"],
"Tôi trả khoản vay như thế nào?":["How do I repay the loan?", "如何偿还贷款？"],
"Tôi đã đọc bảng chi phí và hợp đồng.":["I have read the cost summary and contract.", "本人已阅读费用表与合同。"],
"Tôi đồng ý cho BuoyUp thực hiện các nội dung trên.":["I agree to let BuoyUp carry out the above.", "本人同意 BuoyUp 执行上述内容。"],
"Tôi đồng ý với":["I agree to BuoyUp’s", "我同意 BuoyUp 的"],
"Tôi đồng ý để BuoyUp chuyển hồ sơ vay và kết quả thẩm định cho các ngân hàng hợp tác dưới đây để họ tự quyết định tham gia cấp vốn trong vòng 30 giây.":["I agree that BuoyUp may share my loan application and assessment results with the partner banks below so that they can each decide whether to join the funding within 30 seconds.", "本人同意 BuoyUp 将本人的贷款申请及审核结果转送给以下合作银行，由其在 30 秒内自行决定是否参与出资。"],
"Tôi đồng ý để BuoyUp xử lý ảnh khuôn mặt của tôi để xác thực danh tính và ký điện tử, và dữ liệu tài chính gồm doanh thu và hóa đơn trên hệ thống thuế (银税互动) cùng ảnh doanh thu tôi tự nộp, để thẩm định khả năng trả nợ.":["I agree that BuoyUp may process my facial images for identity verification and electronic signing, and my financial data, including revenue and invoices on the tax system (银税互动) and the revenue screenshots I submit myself, to assess my ability to repay.", "本人同意 BuoyUp 处理本人的面部图像，用于身份验证和电子签名；并处理本人的财务数据，包括税务系统（银税互动）中的营业收入和发票，以及本人自行提交的营业收入截图，用于评估还款能力。"],
"Tôi ủy quyền cho WeBank (ngân hàng dẫn đầu) và các ngân hàng hợp tác trong danh sách đính kèm tra cứu báo cáo tín dụng của tôi tại tổ chức thông tin tín dụng được cấp phép, và nhận điểm rủi ro liên ngân hàng (FATE) do các ngân hàng cùng huấn luyện mà không trao đổi dữ liệu gốc.":["I authorize WeBank (the lead bank) and the partner banks in the attached list to look up my credit report at a licensed credit information organization, and to receive the cross-bank risk score (FATE) jointly trained by the banks without exchanging raw data.", "本人授权 WeBank（牵头银行）及所附名单中的合作银行，向持牌征信机构查询本人的信用报告，并获取由各银行在不交换原始数据的情况下联合训练的跨行风险评分（FATE）。"],
