"{x}: tiền trả nợ {x} tệ bằng {x} % doanh thu ước tính ({x} tệ, {x}). Trên {x} % là mức BuoyUp coi là nặng. Để tiền hàng về WeBank đầy đủ sẽ cho con số chính xác hơn.":["{x}: debt repayment of {x} CNY equals {x} % of estimated revenue ({x} CNY, {x}). Above {x} % is what BuoyUp considers heavy. Routing all payouts to WeBank will give a more accurate figure.", "{x}：还款额 {x} 元，占估算营收的 {x} %（{x} 元，{x}）。超过 {x} % 即被 BuoyUp 视为负担较重。让货款全部进入 WeBank 可得到更准确的数字。"],
"{x}: tỷ lệ chỉ được tối đa 2 chữ số thập phân (theo phần trăm).":["{x}: share may have at most 2 decimal places (in percent).", "{x}：比例最多保留 2 位小数（按百分比）。"],
