"Trên BuoyUp, hồ sơ, hạn mức và lịch trả được tính đầy đủ theo quy trình, nhưng chưa có khoản tiền nào được chuyển cho bạn. Khoản vay chỉ có hiệu lực khi ngân hàng đối tác ký hợp đồng chính thức với bạn.":["On BuoyUp, the application, limit and repayment schedule are worked out in full, but no money has been transferred to you. A loan takes effect only when a partner bank signs a formal contract with you.", "在 BuoyUp 上，申请、额度和还款计划都会按流程完整计算，但尚未向您转入任何款项。贷款仅在合作银行与您签订正式合同后生效。"],
"Đây là ước tính, cần nộp chứng từ.":["This is an estimate; documents are required.", "此为估算，需提交凭证。"],
